import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
from scipy import stats
import warnings
warnings.filterwarnings('ignore')

sns.set_theme(style="whitegrid", palette="muted")

# 1. Load and Clean Data
df = pd.read_csv('/app/benchmark/data.csv')
# Date parsing: %d-%m-%y. Years <= 25 are 2000+, but strptime might handle 00-68 as 2000-2068.
df['Date'] = pd.to_datetime(df['Date'], format='%d-%m-%y')
df = df.sort_values('Date').reset_index(drop=True)
df['Return'] = df['Close'].pct_change()
df['Log_Return'] = np.log(df['Close'] / df['Close'].shift(1))

# 2. KPIs
start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
years = len(df) / 252
cagr = (end_price / start_price) ** (1 / years) - 1
ann_vol = df['Return'].std() * np.sqrt(252)
rolling_max = df['Close'].cummax()
drawdown = df['Close'] / rolling_max - 1
max_dd = drawdown.min()
avg_vol = df['Volume'].mean()
sharpe = cagr / ann_vol

kpi_html = f"""
<div class="kpi-container">
    <div class="kpi-box"><h3>Annualized Return</h3><p>{cagr:.2%}</p></div>
    <div class="kpi-box"><h3>Annualized Volatility</h3><p>{ann_vol:.2%}</p></div>
    <div class="kpi-box"><h3>Max Drawdown</h3><p>{max_dd:.2%}</p></div>
    <div class="kpi-box"><h3>Sharpe Ratio</h3><p>{sharpe:.2f}</p></div>
    <div class="kpi-box"><h3>Avg Daily Volume</h3><p>{avg_vol:,.0f}</p></div>
</div>
"""

# Helper function to embed plots
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

charts_html = ""

# --- Section 1: Market Overview & Long-Term Price Trend ---
fig, ax = plt.subplots(figsize=(12, 6))
ax.plot(df['Date'], df['Close'], color='goldenrod', linewidth=1.5)
ax.fill_between(df['Date'], df['Close'], color='goldenrod', alpha=0.1)
ax.set_title('Gold Price Evolution (2000-2025)', fontsize=16, fontweight='bold')
ax.set_ylabel('Price (USD)')
ax.set_xlabel('')
charts_html += f"<h2>Market Overview & Long-Term Price Trend</h2>"
charts_html += f"<p>The chart below illustrates the multi-decade trajectory of Gold, highlighting significant bull markets and consolidation phases.</p>"
charts_html += f"<img src='data:image/png;base64,{fig_to_base64(fig)}'>"

# Drawdown chart
fig, ax = plt.subplots(figsize=(12, 4))
ax.fill_between(df['Date'], drawdown, 0, color='red', alpha=0.3)
ax.plot(df['Date'], drawdown, color='red', linewidth=1)
ax.set_title('Historical Drawdowns', fontsize=14)
ax.set_ylabel('Drawdown')
ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda y, _: '{:.0%}'.format(y)))
charts_html += f"<img src='data:image/png;base64,{fig_to_base64(fig)}'>"

# --- Section 2: Volatility Analysis & Regime Detection ---
df['Rolling_Vol_60'] = df['Return'].rolling(window=60).std() * np.sqrt(252)
# Regime thresholds
p33 = df['Rolling_Vol_60'].quantile(0.33)
p75 = df['Rolling_Vol_60'].quantile(0.75)
p95 = df['Rolling_Vol_60'].quantile(0.95)

def get_regime(v):
    if pd.isna(v): return 'Unknown'
    if v > p95: return 'Crisis'
    if v > p75: return 'High Vol'
    if v > p33: return 'Normal'
    return 'Low Vol'

df['Regime'] = df['Rolling_Vol_60'].apply(get_regime)

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 10), sharex=True)
ax1.plot(df['Date'], df['Close'], color='gray', alpha=0.6, linewidth=1)
ax1.scatter(df.loc[df['Regime'] == 'Crisis', 'Date'], df.loc[df['Regime'] == 'Crisis', 'Close'], color='red', s=10, label='Crisis', zorder=5)
ax1.set_title('Price Overlaid with Crisis Regimes', fontsize=14)
ax1.legend()
ax1.set_ylabel('Price (USD)')

ax2.plot(df['Date'], df['Rolling_Vol_60'], color='purple', linewidth=1.5)
ax2.axhline(p95, color='red', linestyle='--', label='95th Pct (Crisis)')
ax2.axhline(p75, color='orange', linestyle='--', label='75th Pct (High Vol)')
ax2.axhline(p33, color='green', linestyle='--', label='33rd Pct (Low Vol)')
ax2.set_title('Rolling 60-Day Annualized Volatility', fontsize=14)
ax2.set_ylabel('Annualized Volatility')
ax2.legend()
charts_html += f"<h2>Volatility Analysis & Regime Detection</h2>"
charts_html += f"<p>Volatility regimes are determined using the 60-day rolling annualized standard deviation. Thresholds are set at the 33rd, 75th, and 95th percentiles to classify Low Vol, Normal, High Vol, and Crisis periods.</p>"
charts_html += f"<img src='data:image/png;base64,{fig_to_base64(fig)}'>"

# --- Section 3: Seasonal & Calendar-Based Patterns ---
df['Month'] = df['Date'].dt.month
df['DayOfWeek'] = df['Date'].dt.dayofweek
monthly_returns = df.groupby(['Month', df['Date'].dt.year])['Return'].sum().unstack()

# Statistical Rigor
# Kruskal-Wallis H-test for monthly seasonality
months_data = [df.dropna()[df.dropna()['Month'] == m]['Return'].values for m in range(1, 13)]
h_stat, p_val = stats.kruskal(*months_data)

fig, ax = plt.subplots(figsize=(10, 5))
sns.boxplot(x='Month', y='Return', data=df, ax=ax, showfliers=False, palette='viridis')
ax.set_title('Return Distribution by Month', fontsize=14)
ax.axhline(0, color='red', linestyle='--', alpha=0.5)
ax.set_xticklabels(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])
charts_html += f"<h2>Seasonal & Calendar-Based Patterns</h2>"
charts_html += f"<p>Kruskal-Wallis H-test for monthly seasonality yields a p-value of <b>{p_val:.4f}</b>. "
if p_val < 0.05:
    charts_html += "This indicates statistically significant differences in returns across months.</p>"
else:
    charts_html += "This indicates that any observed differences across months are likely due to noise and lack statistical significance.</p>"
charts_html += f"<img src='data:image/png;base64,{fig_to_base64(fig)}'>"

# --- Section 4: Return Distribution & Tail Risk ---
fig, ax = plt.subplots(figsize=(10, 6))
sns.histplot(df['Return'].dropna(), bins=100, kde=True, ax=ax, color='steelblue')
ax.set_title('Daily Return Distribution', fontsize=14)
ax.set_xlabel('Daily Return')

skewness = df['Return'].skew()
kurtosis = df['Return'].kurtosis()

charts_html += f"<h2>Return Distribution & Tail Risk</h2>"
charts_html += f"<p>The distribution of daily returns exhibits a skewness of <b>{skewness:.2f}</b> and an excess kurtosis of <b>{kurtosis:.2f}</b>. High kurtosis indicates 'fat tails', meaning extreme events (both positive and negative) occur more frequently than a normal distribution would predict.</p>"
charts_html += f"<img src='data:image/png;base64,{fig_to_base64(fig)}'>"

# --- Section 5: Momentum Dynamics & Liquidity Behavior ---
df['MA_50'] = df['Close'].rolling(window=50).mean()
df['MA_200'] = df['Close'].rolling(window=200).mean()

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 10), gridspec_kw={'height_ratios': [3, 1]}, sharex=True)
ax1.plot(df['Date'], df['Close'], color='goldenrod', label='Close', alpha=0.7)
ax1.plot(df['Date'], df['MA_50'], color='blue', label='50-Day MA', linewidth=1)
ax1.plot(df['Date'], df['MA_200'], color='red', label='200-Day MA', linewidth=1)
ax1.set_title('Price & Moving Averages (Momentum)', fontsize=14)
ax1.legend()
ax1.set_ylabel('Price (USD)')

# Volume
ax2.bar(df['Date'], df['Volume'], color='gray', alpha=0.5, width=2)
ax2.set_title('Trading Volume', fontsize=14)
ax2.set_ylabel('Volume')
charts_html += f"<h2>Momentum Dynamics & Liquidity Behavior</h2>"
charts_html += f"<p>Moving average crossovers (e.g., 50-day and 200-day) are classic momentum indicators. The volume profile highlights liquidity trends, though early-year data (pre-2003) often features zero volume artifacts.</p>"
charts_html += f"<img src='data:image/png;base64,{fig_to_base64(fig)}'>"

# --- Section 6: Key Takeaways ---
charts_html += f"<h2>Key Takeaways & Forward-Looking Considerations</h2>"
charts_html += f"""
<ul>
    <li><b>Persistent Trend & Strong Risk-Adjusted Returns:</b> Gold has demonstrated a strong upward trajectory with a CAGR of {cagr:.2%}, making it a highly effective long-term asset.</li>
    <li><b>Volatility Clustering:</b> Volatility is not constant. Periods of stress clearly show regime shifts into the top 5% of volatility readings, confirming gold's reactivity to macro crises.</li>
    <li><b>Fat Tails:</b> The return distribution has significant excess kurtosis ({kurtosis:.2f}). Extreme outliers are a feature, not a bug, of gold's price action.</li>
    <li><b>Drawdown Profile:</b> Despite its safe-haven status, gold has historically experienced severe drawdowns (max {max_dd:.2%}), emphasizing the need for disciplined position sizing.</li>
</ul>
"""

# Assembly
html_template = f"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Gold Price Dynamics: Analyst Brief</title>
    <style>
        body {{
            font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            line-height: 1.6;
            color: #333;
            max-width: 1000px;
            margin: 0 auto;
            padding: 20px;
            background-color: #f9fbfd;
        }}
        h1 {{
            color: #2c3e50;
            border-bottom: 2px solid #goldenrod;
            padding-bottom: 10px;
        }}
        h2 {{
            color: #34495e;
